"""EM-7: tabulate near/outside-X city labels across all data files; check s08 in final results. Read-only."""
import json, re, sys
ROOT = "/Users/annikamugin/Documents/deal-requirements-board-review-eval"
PAT = re.compile(r"\b(near|outside(?: of)?|just (?:north|south|east|west) of|(?:north|south|east|west) of|"
                 r"suburbs? of|outskirts of|around|close to|minutes? from|miles? from|area of|edge of)\b", re.I)
for fn in ["posts.jsonl", "holdout.jsonl", "holdout_v3.jsonl", "red_team.jsonl"]:
    print("==", fn)
    for ln, line in enumerate(open(f"{ROOT}/data/{fn}"), 1):
        if not line.strip():
            continue
        r = json.loads(line)
        text = r.get("text", "")
        lab = r.get("label", {})
        for m in PAT.finditer(text):
            ctx = text[max(0, m.start() - 15): m.end() + 30].replace("\n", " ")
            print(f"  L{ln} {r['id']} deal={lab.get('is_deal_request')} city={lab.get('city')!r} "
                  f"adj={r.get('adjudication')} | ...{ctx}...")
print("== line 8 of posts.jsonl starts:", open(f"{ROOT}/data/posts.jsonl").read().splitlines()[7][:55])
res = json.load(open(f"{ROOT}/results/claude_20261024T234359Z.json"))
def find(o, path=""):
    if isinstance(o, dict):
        if o.get("id") == "s08":
            print("== result entry for s08 at", path, json.dumps(o)[:900])
        for k, v in o.items():
            find(v, path + "/" + k)
    elif isinstance(o, list):
        for i, v in enumerate(o):
            find(v, f"{path}[{i}]")
find(res)

